// Generated by `just generate` from `src/plugins/dotclaude/slices/spec/adapters/specify.ts`. Edit the source and run `just generate`.
// `dotclaude-spec specify <id> [--size trivial|medium|large] [--capability <name>] [--json]`.
// On an id that is free, it creates the change in `draft`: `change.md`, `events.jsonl`, and the files of its size.
//   trivial: the requirements are in `change.md`. medium: `requirements/<capability>.md`. large: also `design.md`.
// On a change that exists, it checks the gate: each requirement has a valid ID, and no marker is open.
//   A trivial or medium change then gets the package `P1` and goes on to `planned`. A large change stops at `specified`.
// The `REQ-1` of a template becomes the next free ID of the store.

import path from "node:path";
import {
  eventsHeader,
  eventsPath,
  FRONT_SCHEMA,
} from "../../../kernel/spec-store.ts";
import { gateSpecified } from "../domain/change-gates.ts";
import { renderFront } from "../domain/front.ts";
import { nextId, requirementsOf } from "../domain/requirements.ts";
import { CHANGE_TRANSITIONS, hasTransition } from "../domain/states.ts";
import { CHANGE_ID, DEFAULT_SIZE, SIZES, type Size } from "../limits.ts";
import {
  CHANGE,
  CHANGE_TRIVIAL,
  DESIGN,
  PACKAGE,
  REQUIREMENTS,
} from "../templates/files.ts";
import { parseArgs } from "./args.ts";
import {
  changeDir,
  changeSources,
  openMarkers,
  readChange,
  requirementSources,
  usedRequirementNumbers,
} from "./files.ts";
import type { Run } from "./run.ts";
import {
  changeState,
  type Moved,
  moveChange,
  printMoved,
  refusedInWorktree,
  stop,
  usage,
} from "./transition.ts";

const USAGE =
  "Usage: dotclaude-spec specify <id> [--size trivial|medium|large] [--capability <name>] [--json]";

const isSize = (value: string): value is Size =>
  (SIZES as readonly string[]).includes(value);

/** Creates the files of a new change in `draft`. */
const create = async (
  run: Run,
  id: string,
  size: Size,
  capability: string,
): Promise<Moved> => {
  const first = nextId(await usedRequirementNumbers(run.store));
  const fill = (text: string): string =>
    text
      .replaceAll("<id>", id)
      .replaceAll("<size>", size)
      .replaceAll("<capability>", capability)
      .replace("REQ-1", `REQ-${first}`);
  const dir = changeDir(id);
  await run.store.write(
    path.posix.join(dir, "change.md"),
    fill(size === "trivial" ? CHANGE_TRIVIAL : CHANGE),
  );
  if (size !== "trivial")
    await run.store.write(
      path.posix.join(dir, "requirements", `${capability}.md`),
      fill(REQUIREMENTS),
    );
  if (size === "large")
    await run.store.write(path.posix.join(dir, "design.md"), fill(DESIGN));
  await run.store.write(eventsPath(id), eventsHeader());
  await run.store.appendEvent(id, {
    at: run.clock.now().toISOString(),
    state: "draft",
  });
  return { change: id, from: "none", to: "draft" };
};

/** The text of the package `P1` of a short-path change: it satisfies each requirement and has the `verify` of the change. */
const shortPackage = (
  id: string,
  satisfies: string[],
  verify: string,
): string => {
  const title = `Implement ${id}`;
  return PACKAGE.replace(
    /^---[\s\S]*?\n---\n/,
    renderFront("package", {
      schema: FRONT_SCHEMA,
      kind: "package",
      id: "P1",
      title,
      wave: "1",
      deps: [],
      owns: [],
      satisfies,
      verify,
      agent: "implementer",
      status: "planned",
    }),
  );
};

export const specifyCommand = async (
  run: Run,
  args: string[],
): Promise<number> => {
  const parsed = parseArgs(args, { values: ["size", "capability"] });
  if (typeof parsed === "string") return usage(run, parsed);
  const [id, extra] = parsed.words;
  const { size, capability = id } = parsed.values;
  if (!id || extra !== undefined) return usage(run, USAGE);
  if (!CHANGE_ID.test(id))
    return usage(run, `The id \`${id}\` is not a change id.`);
  if (refusedInWorktree(run, "specifies a change")) return 1;
  const events = await run.store.events(id);
  if (events === null) {
    if (run.store.exists(changeDir(id)))
      return stop(
        run,
        `\`${changeDir(id)}\` exists and has no \`events.jsonl\`.`,
      );
    const chosen = size ?? DEFAULT_SIZE;
    if (!isSize(chosen))
      return usage(
        run,
        `The size is ${SIZES.map((s) => `\`${s}\``).join(", ")}.`,
      );
    if (!CHANGE_ID.test(capability ?? ""))
      return usage(run, `The capability \`${capability}\` is not a name.`);
    printMoved(
      run,
      "specify",
      await create(run, id, chosen, capability ?? id),
      parsed.json,
    );
    return 0;
  }
  if (size !== undefined)
    return usage(run, "The size is set when the change is created.");
  const state = changeState(events);
  const change = await readChange(run.store, id);
  if (change === null)
    return stop(run, `The change \`${id}\` has no \`change.md\`.`);
  const short = change.size !== "large";
  const step = {
    from: state,
    command: "specify",
    to: state === "draft" ? "specified" : "planned",
  } as const;
  if (
    !hasTransition(CHANGE_TRANSITIONS, step) ||
    (state === "specified" && !short)
  )
    return stop(
      run,
      `The change \`${id}\` is \`${state}\`, and \`specify\` cannot move it${state === "specified" ? ". Run `plan` for a large change" : ""}.`,
    );
  const found = requirementSources(await changeSources(run.store, id)).flatMap(
    (s) => requirementsOf(s.text),
  );
  if (found.every((r) => r.requirements.length === 0))
    return stop(run, `The change \`${id}\` has no requirement.`);
  const gate = gateSpecified({
    badIds: found.reduce((n, r) => n + r.errors.length, 0),
    openMarkers: await openMarkers(run.store, id),
  });
  if (!gate.ok) return stop(run, gate.reason);
  const file = path.posix.join(changeDir(id), "packages", "P1.md");
  if (short && run.store.exists(file))
    return stop(run, `\`${file}\` exists already.`);
  const first =
    state === "draft" ? await moveChange(run, id, "specified") : undefined;
  if (!short) {
    printMoved(
      run,
      "specify",
      first ?? { change: id, from: state, to: state },
      parsed.json,
    );
    return 0;
  }
  await run.store.write(
    file,
    shortPackage(
      id,
      found.flatMap((r) => r.requirements.map((q) => `REQ-${q.id}`)),
      change.verify,
    ),
  );
  const moved = await moveChange(run, id, "planned");
  printMoved(
    run,
    "specify",
    { ...moved, from: first?.from ?? moved.from },
    parsed.json,
  );
  return 0;
};
